script:
const mobileRegex = /^\d{12}$/;

function validate_cnic_details(frm) {
	const {
		custom_cnic_no,
		custom_cnic_issue_date,
		custom_cnic_expiry_date,
	} = frm.doc;

	// CNIC VALIDATION
	if (custom_cnic_no) {
		const cnicRegex = /^\d{13}$/;
		if (!cnicRegex.test(custom_cnic_no)) {
			frappe.throw(__('CNIC must be exactly 13 digits without dashes.'));
		}
		if (custom_cnic_no === "0000000000000") {
			frappe.throw(__('Invalid CNIC number.'));
		}
	}

	// DATE VALIDATIONS
	if (custom_cnic_issue_date) {
		const today = frappe.datetime.get_today();
		if (custom_cnic_issue_date > today) {
			frappe.throw(__('CNIC Issue Date cannot be in the future.'));
		}
	}

	if (custom_cnic_expiry_date) {
		const today = frappe.datetime.get_today();
		if (custom_cnic_expiry_date < today) {
			frappe.throw(__('CNIC Expiry Date cannot be in the past.'));
		}
	}

	if (custom_cnic_issue_date && custom_cnic_expiry_date) {
		if (custom_cnic_expiry_date <= custom_cnic_issue_date) {
			frappe.throw(__('CNIC Expiry Date must be after Issue Date.'));
		}
	}
}

function validate_mobile_no(frm) {
	const { custom_father_mobile, custom_spouse_mobile, mobile_no, custom_phone_no_1, custom_phone_no_2 } = frm.doc;

	if (custom_phone_no_1 && !mobileRegex.test(custom_phone_no_1)) {
		frappe.throw(__('Phone 1 must be exactly 12 digits.'));
	}

	if (custom_phone_no_2 && !mobileRegex.test(custom_phone_no_2)) {
		frappe.throw(__('Phone 2 must be exactly 12 digits.'));
	}

	if (custom_spouse_mobile && !mobileRegex.test(custom_spouse_mobile)) {
		frappe.throw(__('Spouse Mobile must be exactly 12 digits.'));
	}

	if (custom_father_mobile && !mobileRegex.test(custom_father_mobile)) {
		frappe.throw(__('Father Mobile must be exactly 12 digits.'));
	}

	if (mobile_no && !mobileRegex.test(mobile_no)) {
		frappe.throw(__('Mobile No must be exactly 12 digits.'));
	}
}

function validate_date_of_birth(frm) {
	const { custom_date_of_birth } = frm.doc;

	if (custom_date_of_birth) {
		const today = new Date();
		const dob = new Date(custom_date_of_birth);

		// Check if date is in the future
		if (dob > today) {
			frappe.throw(__('Date of Birth cannot be in the future.'));
		}

		// Calculate age
		let age = today.getFullYear() - dob.getFullYear();
		const monthDiff = today.getMonth() - dob.getMonth();

		// Adjust age if birthday hasn't occurred this year
		if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < dob.getDate())) {
			age--;
		}

		// Check if age is less than 18
		if (age < 18) {
			frappe.throw(__('You must be at least 18 years old.'));
		}

		// Check if age is more than 65
		if (age > 65) {
			frappe.throw(__('Age cannot be more than 65 years.'));
		}
	}
}

function validate_names(frm) {
	const { customer_name, custom_spouse_name, custom_father_name } = frm.doc;
	const nameRegex = /^[a-zA-Z\s]+$/; // Only alphabets and spaces allowed

	if (customer_name && !nameRegex.test(customer_name)) {
		frappe.throw(__('Customer Name must contain only alphabets and spaces.'));
	}

	if (custom_spouse_name && !nameRegex.test(custom_spouse_name)) {
		frappe.throw(__('Spouse Name must contain only alphabets and spaces.'));
	}

	if (custom_father_name && !nameRegex.test(custom_father_name)) {
		frappe.throw(__('Father Name must contain only alphabets and spaces.'));
	}
}

frappe.ui.form.on('Customer', {
	validate: (frm) => {
		validate_cnic_details(frm);
		validate_mobile_no(frm);
		validate_date_of_birth(frm);
		validate_names(frm);
	},

	custom_cnic_no: (frm) => {
		validate_cnic_details(frm);
	},

	custom_cnic_expiry_date: (frm) => {
		validate_cnic_details(frm);
	},

	custom_cnic_issue_date: (frm) => {
		validate_cnic_details(frm);
	},

	custom_spouse_mobile: (frm) => {
		validate_mobile_no(frm);
	},

	custom_phone_no_1: (frm) => {
		validate_mobile_no(frm);
	},

	custom_phone_no_2: (frm) => {
		validate_mobile_no(frm);
	},

	mobile_no: (frm) => {
		validate_mobile_no(frm);
	},

	custom_father_mobile: (frm) => {
		validate_mobile_no(frm);
	},

	custom_date_of_birth: (frm) => {
		validate_date_of_birth(frm);
	},

	customer_name: (frm) => {
		validate_names(frm);
	},

	custom_spouse_name: (frm) => {
		validate_names(frm);
	},

	custom_father_name: (frm) => {
		validate_names(frm);
	}
});
